local function checkpointLabel(self, id)
    do
        local i = 0
        while i < #Tower.checkpoints do
            if Tower.checkpoints[i + 1].id == id then
                return (Tower.FLOORS[Tower.checkpoints[i + 1].floor + 1] .. "·") .. Tower.checkpoints[i + 1].label
            end
            i = i + 1
        end
    end
    return id
end
