        c.r,
        c.g,
        c.b,
        c.a
    )
end
local function makeLabel(self, parent, size, x, y, ax, ay, color)
    local lb = Label(nil, FONT, size)
    if lb == nil then
        return nil
    end
    lb.anchor = Vec2(nil, ax, ay)
    lb.position = Vec2(nil, x, y)
    lb.color = Color(
        nil,
        color.r,
        color.g,
        color.b,
        color.a
    )
    lb:addTo(parent)
    return lb
end
